INSERT INTO public.quizzes (id, title, subject, grade, questions, created_by, is_published, description, quiz_type, difficulty_level, time_limit_minutes, passing_score_percentage, total_questions, allow_retakes, show_answers_after_submission, tags, metadata)
SELECT id, title, subject, grade, questions, created_by, is_published, description, quiz_type, difficulty_level, time_limit_minutes, passing_score_percentage, total_questions, allow_retakes, show_answers_after_submission, tags, metadata FROM jsonb_populate_recordset(NULL::public.quizzes, $smartbridge$[{"id":"4858a516-6fd8-5e2e-80d5-567b1ff18f8d","title":"Mathematics · Grade 11 · Term 2 selection · Set B: Mixed revision","subject":"Mathematics","grade":"Grade 11","questions":[{"question":"Two sides of a triangle are 6 cm and 8 cm with included angle 30°. Find its area.","options":["24 cm²","12 cm²","48 cm²","14 cm²"],"correct_index":1,"explanation":"Area = ½ab sin C = ½ × 6 × 8 × ½ = 12 cm². The stated angle must be between the sides used.","cognitive_level":{"code":"L2","label":"Routine procedures","band":"middle"}},{"question":"An asset of R10 000 depreciates by 10% annually on reducing balance. Value after 2 years?","options":["R8 100","R8 000","R9 000","R12 100"],"correct_index":0,"explanation":"Use 10 000(0.9)² = 8 100. In year two the 10% applies to R9 000, not the original value.","cognitive_level":{"code":"L2","label":"Routine procedures","band":"middle"}},{"question":"A cone has radius 3 cm and perpendicular height 4 cm. Find its volume.","options":["36π cm³","16π cm³","9π cm³","12π cm³"],"correct_index":3,"explanation":"V = ⅓πr²h = ⅓π × 9 × 4 = 12π cm³. Slant height is not used for volume.","cognitive_level":{"code":"L2","label":"Routine procedures","band":"middle"}},{"question":"Simplify √50 in surd form.","options":["5√2","25√2","2√5","10√5"],"correct_index":0,"explanation":"Factor 50 as 25×2, so √50 = √25 × √2 = 5√2. Only a perfect-square factor leaves the root.","cognitive_level":{"code":"L2","label":"Routine procedures","band":"middle"}},{"question":"A cone and cylinder have equal radii. The cone must have the same volume as the cylinder. How must their perpendicular heights compare?","options":["The cone's height must equal the cylinder's.","The cone's height must be one third of the cylinder's.","The cone's height must be three times the cylinder's.","The cone's height must be nine times the cylinder's."],"correct_index":2,"explanation":"Equate ⅓πr²h_cone=πr²h_cylinder. Cancelling the common base area gives h_cone=3h_cylinder; compare formulas rather than the shapes' appearance.","cognitive_level":{"code":"L3","label":"Complex procedures","band":"higher"}}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Mixed grade revision drawn from the other two terms. Includes later-term topics; revisit after studying those topics. Questions are reused deliberately across revision sets.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":5,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-2","formative","math"],"metadata":{"term":2,"focus":"Mixed revision: Trigonometric rules, probability and finance; Patterns and measurement revision","language":"en","content_version":"2026-10-21.2","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=d9piy_Yst2E%3d&tabid=3205&portalid=0&mid=10752","caps_url":"https://www.education.gov.za/Portals/0/CD/National%20Curriculum%20Statements%20and%20Vocational/CAPS%20FET%20_%20MATHEMATICS%20_%20GR%2010-12%20_%20Web_1133.pdf","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/math-11","coverage":"Selected grade revision from other terms, including later-term content. Not a second paper covering only the selected term.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content.","set_id":"B","set_label":"Mixed grade revision","cognitive_framework":"CAPS subject taxonomy","cognitive_levels":["Knowledge","Routine procedures","Complex procedures","Problem solving"],"classification_status":"Draft author classification; independent moderation pending","assessment_note":"Five-question formative samples do not reproduce formal examination mark weightings or assess extended written responses.","source_terms":[3,4],"atp_urls":["https://www.education.gov.za/LinkClick.aspx?fileticket=d9piy_Yst2E%3d&tabid=3205&portalid=0&mid=10752"],"question_reuse":"Revision questions recur across term-focused and mixed sets; Set A and Set B within the same selection do not share questions."}},{"id":"4b58426f-8469-5df6-bac7-7214200e784e","title":"Mathematics · Grade 11 · Term 3 selection · Set B: Mixed revision","subject":"Mathematics","grade":"Grade 11","questions":[{"question":"The angle at the centre of a circle is 100°. What is the angle at the circumference subtended by the same arc?","options":["50°","100°","200°","80°"],"correct_index":0,"explanation":"The angle at the centre is twice the angle at the circumference on the same arc. Divide 100° by 2.","cognitive_level":{"code":"L2","label":"Routine procedures","band":"middle"}},{"question":"For y = 3/x + 1, which line is a horizontal asymptote?","options":["x = 1","y = 0","x = 0","y = 1"],"correct_index":3,"explanation":"As the magnitude of x grows, 3/x approaches 0, so y approaches 1. x = 0 is the vertical asymptote.","cognitive_level":{"code":"L1","label":"Knowledge","band":"lower"}},{"question":"A cone has radius 3 cm and perpendicular height 4 cm. Find its volume.","options":["36π cm³","16π cm³","9π cm³","12π cm³"],"correct_index":3,"explanation":"V = ⅓πr²h = ⅓π × 9 × 4 = 12π cm³. Slant height is not used for volume.","cognitive_level":{"code":"L2","label":"Routine procedures","band":"middle"}},{"question":"Simplify √50 in surd form.","options":["5√2","25√2","2√5","10√5"],"correct_index":0,"explanation":"Factor 50 as 25×2, so √50 = √25 × √2 = 5√2. Only a perfect-square factor leaves the root.","cognitive_level":{"code":"L2","label":"Routine procedures","band":"middle"}},{"question":"A cone and cylinder have equal radii. The cone must have the same volume as the cylinder. How must their perpendicular heights compare?","options":["The cone's height must equal the cylinder's.","The cone's height must be one third of the cylinder's.","The cone's height must be three times the cylinder's.","The cone's height must be nine times the cylinder's."],"correct_index":2,"explanation":"Equate ⅓πr²h_cone=πr²h_cylinder. Cancelling the common base area gives h_cone=3h_cylinder; compare formulas rather than the shapes' appearance.","cognitive_level":{"code":"L3","label":"Complex procedures","band":"higher"}}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Mixed grade revision drawn from the other two terms. Includes later-term topics; revisit after studying those topics. Questions are reused deliberately across revision sets.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":5,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-3","formative","math"],"metadata":{"term":3,"focus":"Mixed revision: Circle geometry, coordinates and functions; Patterns and measurement revision","language":"en","content_version":"2026-10-21.2","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=d9piy_Yst2E%3d&tabid=3205&portalid=0&mid=10752","caps_url":"https://www.education.gov.za/Portals/0/CD/National%20Curriculum%20Statements%20and%20Vocational/CAPS%20FET%20_%20MATHEMATICS%20_%20GR%2010-12%20_%20Web_1133.pdf","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/math-11","coverage":"Selected grade revision from other terms, including later-term content. Not a second paper covering only the selected term.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content.","set_id":"B","set_label":"Mixed grade revision","cognitive_framework":"CAPS subject taxonomy","cognitive_levels":["Knowledge","Routine procedures","Complex procedures","Problem solving"],"classification_status":"Draft author classification; independent moderation pending","assessment_note":"Five-question formative samples do not reproduce formal examination mark weightings or assess extended written responses.","source_terms":[2,4],"atp_urls":["https://www.education.gov.za/LinkClick.aspx?fileticket=d9piy_Yst2E%3d&tabid=3205&portalid=0&mid=10752"],"question_reuse":"Revision questions recur across term-focused and mixed sets; Set A and Set B within the same selection do not share questions."}},{"id":"c8b87314-4676-5e52-b798-8a3a1e76c009","title":"Mathematics · Grade 11 · Term 4 selection · Set B: Mixed revision","subject":"Mathematics","grade":"Grade 11","questions":[{"question":"The angle at the centre of a circle is 100°. What is the angle at the circumference subtended by the same arc?","options":["50°","100°","200°","80°"],"correct_index":0,"explanation":"The angle at the centre is twice the angle at the circumference on the same arc. Divide 100° by 2.","cognitive_level":{"code":"L2","label":"Routine procedures","band":"middle"}},{"question":"For y = 3/x + 1, which line is a horizontal asymptote?","options":["x = 1","y = 0","x = 0","y = 1"],"correct_index":3,"explanation":"As the magnitude of x grows, 3/x approaches 0, so y approaches 1. x = 0 is the vertical asymptote.","cognitive_level":{"code":"L1","label":"Knowledge","band":"lower"}},{"question":"A triangle has sides 5 and 7 with included angle 60°. Find the square of the opposite side.","options":["74","109","39","25"],"correct_index":2,"explanation":"Cosine rule: c² = 5²+7²−2(5)(7)cos60° = 74−35 = 39. The question asks for c², not c.","cognitive_level":{"code":"L2","label":"Routine procedures","band":"middle"}},{"question":"Events A and B are independent with probabilities 0.4 and 0.5. Find P(A and B).","options":["0.90","0.10","0.45","0.20"],"correct_index":3,"explanation":"For independent events multiply: 0.4 × 0.5 = 0.20. Adding instead would not give the intersection.","cognitive_level":{"code":"L2","label":"Routine procedures","band":"middle"}},{"question":"Independent events A and B have probabilities 0.4 and 0.5. A learner calculates P(A or B)=0.9. Which correction explains the error?","options":["Add the overlap 0.2, giving 1.1.","Replace the union with 0.4×0.5=0.2.","Subtract the overlap 0.2, giving 0.7.","Independent means the overlap is zero, so 0.9 is correct."],"correct_index":2,"explanation":"Independence gives P(A and B)=0.4×0.5=0.2; it does not mean mutually exclusive. The addition rule gives 0.4+0.5−0.2=0.7.","cognitive_level":{"code":"L3","label":"Complex procedures","band":"higher"}}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Mixed grade revision drawn from the other two terms. Includes later-term topics; revisit after studying those topics. Questions are reused deliberately across revision sets.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":5,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-4","formative","math"],"metadata":{"term":4,"focus":"Mixed revision: Circle geometry, coordinates and functions; Trigonometric rules, probability and finance","language":"en","content_version":"2026-10-21.2","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=d9piy_Yst2E%3d&tabid=3205&portalid=0&mid=10752","caps_url":"https://www.education.gov.za/Portals/0/CD/National%20Curriculum%20Statements%20and%20Vocational/CAPS%20FET%20_%20MATHEMATICS%20_%20GR%2010-12%20_%20Web_1133.pdf","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/math-11","coverage":"Selected grade revision from other terms, including later-term content. Not a second paper covering only the selected term.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content.","set_id":"B","set_label":"Mixed grade revision","cognitive_framework":"CAPS subject taxonomy","cognitive_levels":["Knowledge","Routine procedures","Complex procedures","Problem solving"],"classification_status":"Draft author classification; independent moderation pending","assessment_note":"Five-question formative samples do not reproduce formal examination mark weightings or assess extended written responses.","source_terms":[2,3],"atp_urls":["https://www.education.gov.za/LinkClick.aspx?fileticket=d9piy_Yst2E%3d&tabid=3205&portalid=0&mid=10752"],"question_reuse":"Revision questions recur across term-focused and mixed sets; Set A and Set B within the same selection do not share questions."}},{"id":"c293c8e3-c3ef-59d3-a526-68d33c737e18","title":"Mathematical Literacy · Grade 11 · Term 2 selection · Set B: Mixed revision","subject":"Mathematical Literacy","grade":"Grade 11","questions":[{"question":"A stall has fixed costs R300, sells items for R20 and spends R5 per item. How many items break even?","options":["15","60","20","12"],"correct_index":2,"explanation":"Each item contributes R20−R5 = R15 towards fixed costs. R300/R15 = 20 items; then total revenue equals total cost.","cognitive_level":{"code":"L3","label":"Applying multi-step procedures","band":"middle"}},{"question":"Actual spending is R3 600; the budget was R3 000. By what percentage did spending exceed the budget?","options":["16.67%","20%","60%","120%"],"correct_index":1,"explanation":"The excess is R600. Divide by the original budget: 600/3 000×100 = 20%, not by actual spending.","cognitive_level":{"code":"L2","label":"Applying routine procedures","band":"lower"}},{"question":"A box is 30 cm × 20 cm × 10 cm. Find its capacity in litres.","options":["6 L","60 L","600 L","0.6 L"],"correct_index":0,"explanation":"Volume = 6 000 cm³. Since 1 000 cm³ = 1 L, capacity is 6 L.","cognitive_level":{"code":"L2","label":"Applying routine procedures","band":"lower"}},{"question":"A shop offers 20% off R450. What do you pay?","options":["R90","R360","R430","R540"],"correct_index":1,"explanation":"Discount = 0.20×450 = R90. Subtract R90 from R450 to get R360; R90 is the saving.","cognitive_level":{"code":"L3","label":"Applying multi-step procedures","band":"middle"}},{"question":"A box holds 6 L by its outside dimensions. A buyer needs to store 6 L of liquid and claims it is guaranteed to fit. Which response is justified?","options":["The outside volume always equals usable liquid capacity.","Six litres means the box has a 6 m length.","Check internal capacity and usable space; outside dimensions do not guarantee 6 L storage.","Wall thickness increases internal capacity."],"correct_index":2,"explanation":"Capacity depends on internal dimensions, wall thickness and any necessary headspace. An external-volume calculation alone does not establish usable storage.","cognitive_level":{"code":"L4","label":"Reasoning and reflecting","band":"higher"}}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Mixed grade revision drawn from the other two terms. Includes later-term topics; revisit after studying those topics. Questions are reused deliberately across revision sets.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":5,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-2","formative","matlit"],"metadata":{"term":2,"focus":"Mixed revision: Break-even, loans and design drawings; Assembly instructions and integrated revision","language":"en","content_version":"2026-10-21.2","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=EqZ41-tXhWA%3d&tabid=3205&portalid=0&mid=10752","caps_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=q8-SkGy43rw%3d&tabid=570&portalid=0&mid=1558","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/matlit-11","coverage":"Selected grade revision from other terms, including later-term content. Not a second paper covering only the selected term.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content.","set_id":"B","set_label":"Mixed grade revision","cognitive_framework":"CAPS subject taxonomy","cognitive_levels":["Knowing","Applying routine procedures","Applying multi-step procedures","Reasoning and reflecting"],"classification_status":"Draft author classification; independent moderation pending","assessment_note":"Five-question formative samples do not reproduce formal examination mark weightings or assess extended written responses.","source_terms":[3,4],"atp_urls":["https://www.education.gov.za/LinkClick.aspx?fileticket=EqZ41-tXhWA%3d&tabid=3205&portalid=0&mid=10752"],"question_reuse":"Revision questions recur across term-focused and mixed sets; Set A and Set B within the same selection do not share questions."}},{"id":"06a3a9d1-bd5a-544d-89cf-b21bf6a1cc16","title":"Mathematical Literacy · Grade 11 · Term 3 selection · Set B: Mixed revision","subject":"Mathematical Literacy","grade":"Grade 11","questions":[{"question":"For this exercise, VAT is 15%. Find VAT on a price of R200 excluding VAT.","options":["R230","R30","R26.09","R15"],"correct_index":1,"explanation":"VAT = 200×0.15 = R30. Add it for a VAT-inclusive price of R230. Use the rate provided in the question.","cognitive_level":{"code":"L2","label":"Applying routine procedures","band":"lower"}},{"question":"A phone plan charges R100 plus R0.50 per minute. What is the total for 120 minutes?","options":["R160","R60","R220","R100"],"correct_index":0,"explanation":"Variable cost = 120×0.50 = R60. Add the R100 fixed charge to get R160.","cognitive_level":{"code":"L2","label":"Applying routine procedures","band":"lower"}},{"question":"A box is 30 cm × 20 cm × 10 cm. Find its capacity in litres.","options":["6 L","60 L","600 L","0.6 L"],"correct_index":0,"explanation":"Volume = 6 000 cm³. Since 1 000 cm³ = 1 L, capacity is 6 L.","cognitive_level":{"code":"L2","label":"Applying routine procedures","band":"lower"}},{"question":"A shop offers 20% off R450. What do you pay?","options":["R90","R360","R430","R540"],"correct_index":1,"explanation":"Discount = 0.20×450 = R90. Subtract R90 from R450 to get R360; R90 is the saving.","cognitive_level":{"code":"L3","label":"Applying multi-step procedures","band":"middle"}},{"question":"A box holds 6 L by its outside dimensions. A buyer needs to store 6 L of liquid and claims it is guaranteed to fit. Which response is justified?","options":["The outside volume always equals usable liquid capacity.","Six litres means the box has a 6 m length.","Check internal capacity and usable space; outside dimensions do not guarantee 6 L storage.","Wall thickness increases internal capacity."],"correct_index":2,"explanation":"Capacity depends on internal dimensions, wall thickness and any necessary headspace. An external-volume calculation alone does not establish usable storage.","cognitive_level":{"code":"L4","label":"Reasoning and reflecting","band":"higher"}}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Mixed grade revision drawn from the other two terms. Includes later-term topics; revisit after studying those topics. Questions are reused deliberately across revision sets.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":5,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-3","formative","matlit"],"metadata":{"term":3,"focus":"Mixed revision: Tax, tariffs and data; Assembly instructions and integrated revision","language":"en","content_version":"2026-10-21.2","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=EqZ41-tXhWA%3d&tabid=3205&portalid=0&mid=10752","caps_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=q8-SkGy43rw%3d&tabid=570&portalid=0&mid=1558","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/matlit-11","coverage":"Selected grade revision from other terms, including later-term content. Not a second paper covering only the selected term.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content.","set_id":"B","set_label":"Mixed grade revision","cognitive_framework":"CAPS subject taxonomy","cognitive_levels":["Knowing","Applying routine procedures","Applying multi-step procedures","Reasoning and reflecting"],"classification_status":"Draft author classification; independent moderation pending","assessment_note":"Five-question formative samples do not reproduce formal examination mark weightings or assess extended written responses.","source_terms":[2,4],"atp_urls":["https://www.education.gov.za/LinkClick.aspx?fileticket=EqZ41-tXhWA%3d&tabid=3205&portalid=0&mid=10752"],"question_reuse":"Revision questions recur across term-focused and mixed sets; Set A and Set B within the same selection do not share questions."}},{"id":"9f9920ad-1b55-5d88-861a-47b598a50b37","title":"Mathematical Literacy · Grade 11 · Term 4 selection · Set B: Mixed revision","subject":"Mathematical Literacy","grade":"Grade 11","questions":[{"question":"For this exercise, VAT is 15%. Find VAT on a price of R200 excluding VAT.","options":["R230","R30","R26.09","R15"],"correct_index":1,"explanation":"VAT = 200×0.15 = R30. Add it for a VAT-inclusive price of R230. Use the rate provided in the question.","cognitive_level":{"code":"L2","label":"Applying routine procedures","band":"lower"}},{"question":"A phone plan charges R100 plus R0.50 per minute. What is the total for 120 minutes?","options":["R160","R60","R220","R100"],"correct_index":0,"explanation":"Variable cost = 120×0.50 = R60. Add the R100 fixed charge to get R160.","cognitive_level":{"code":"L2","label":"Applying routine procedures","band":"lower"}},{"question":"A loan of R2 000 costs R150 interest and R50 in fees. Find the total repayment.","options":["R2 150","R200","R1 800","R2 200"],"correct_index":3,"explanation":"Add principal, interest and fees: 2 000+150+50 = R2 200. Fees also affect borrowing cost.","cognitive_level":{"code":"L2","label":"Applying routine procedures","band":"lower"}},{"question":"A design drawing uses 1:20. A table is 1.6 m long in real life. Find its drawing length in cm.","options":["8 cm","80 cm","32 cm","0.08 cm"],"correct_index":0,"explanation":"Convert 1.6 m to 160 cm, then divide by 20. A reduced drawing is shorter than the real table.","cognitive_level":{"code":"L2","label":"Applying routine procedures","band":"lower"}},{"question":"A stall's fixed costs are R300, selling price R20 and variable cost R5 per item. It can sell at most 18 items. Which conclusion follows?","options":["It breaks even because revenue exceeds R300.","It makes R60 profit because 18×20−300=60.","It cannot break even; 18 sales leave a R30 loss.","It needs only 15 sales because 300÷20=15."],"correct_index":2,"explanation":"At 18 sales revenue is R360, but costs are R300+R90=R390. The loss is R30. Contribution is R15 per item, requiring 20 sales to break even.","cognitive_level":{"code":"L4","label":"Reasoning and reflecting","band":"higher"}}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Mixed grade revision drawn from the other two terms. Includes later-term topics; revisit after studying those topics. Questions are reused deliberately across revision sets.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":5,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-4","formative","matlit"],"metadata":{"term":4,"focus":"Mixed revision: Tax, tariffs and data; Break-even, loans and design drawings","language":"en","content_version":"2026-10-21.2","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=EqZ41-tXhWA%3d&tabid=3205&portalid=0&mid=10752","caps_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=q8-SkGy43rw%3d&tabid=570&portalid=0&mid=1558","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/matlit-11","coverage":"Selected grade revision from other terms, including later-term content. Not a second paper covering only the selected term.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content.","set_id":"B","set_label":"Mixed grade revision","cognitive_framework":"CAPS subject taxonomy","cognitive_levels":["Knowing","Applying routine procedures","Applying multi-step procedures","Reasoning and reflecting"],"classification_status":"Draft author classification; independent moderation pending","assessment_note":"Five-question formative samples do not reproduce formal examination mark weightings or assess extended written responses.","source_terms":[2,3],"atp_urls":["https://www.education.gov.za/LinkClick.aspx?fileticket=EqZ41-tXhWA%3d&tabid=3205&portalid=0&mid=10752"],"question_reuse":"Revision questions recur across term-focused and mixed sets; Set A and Set B within the same selection do not share questions."}},{"id":"09c54884-b883-529f-9975-a261b2c80da8","title":"Physical Sciences · Grade 11 · Term 2 selection · Set B: Mixed revision","subject":"Physical Sciences","grade":"Grade 11","questions":[{"question":"A sample has mass 8 g and molar mass 16 g·mol⁻¹. Find its amount of substance.","options":["2 mol","128 mol","24 mol","0.5 mol"],"correct_index":3,"explanation":"n=m/M=8/16=0.5 mol. Dividing by molar mass cancels grams and leaves moles.","cognitive_level":{"code":"L3","label":"Analysis and application","band":"middle"}},{"question":"In an exothermic reaction, how does the enthalpy of products compare with reactants?","options":["It is higher, so ΔH is positive","It must be exactly equal","It is lower, so ΔH is negative","It cannot be compared"],"correct_index":2,"explanation":"Energy is released to surroundings. ΔH=H(products)−H(reactants) is negative because products have lower enthalpy.","cognitive_level":{"code":"L2","label":"Comprehension","band":"lower"}},{"question":"For Zn → Zn²⁺ + 2e⁻, what happens to zinc?","options":["It is reduced by losing electrons","It is oxidised by losing electrons","It gains two electrons","Its oxidation number decreases"],"correct_index":1,"explanation":"Oxidation is loss of electrons. Zinc's oxidation number rises from 0 to +2.","cognitive_level":{"code":"L2","label":"Comprehension","band":"lower"}},{"question":"Which equation shows neutralisation of HCl by NaOH?","options":["HCl + NaOH → H₂ + NaClO","HCl + NaOH → Na + Cl + O₂","HCl + NaOH → NaCl + H₂O","HCl + NaOH → NaCl only"],"correct_index":2,"explanation":"The acid and base produce salt and water. Check that hydrogen and oxygen atoms are conserved as well as sodium and chlorine.","cognitive_level":{"code":"L2","label":"Comprehension","band":"lower"}},{"question":"A learner dilutes 100 mL of 0.4 mol·dm⁻³ solution to a final volume of 400 mL and claims the moles become one quarter. Which correction is right?","options":["Moles become 0.01 mol; concentration stays 0.4 mol·dm⁻³.","Both moles and concentration remain unchanged.","Moles remain 0.04 mol; concentration becomes 0.1 mol·dm⁻³.","Adding water creates additional solute moles."],"correct_index":2,"explanation":"Initial moles are 0.4×0.100=0.04 mol. Without loss or reaction, dilution changes volume, not solute amount. Final concentration is 0.04/0.400=0.1 mol·dm⁻³.","cognitive_level":{"code":"L3","label":"Analysis and application","band":"middle"}}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Mixed grade revision drawn from the other two terms. Includes later-term topics; revisit after studying those topics. Questions are reused deliberately across revision sets.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":5,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-2","formative","phsc"],"metadata":{"term":2,"focus":"Mixed revision: Stoichiometry, gases and energy change; Acid–base and redox reactions","language":"en","content_version":"2026-10-21.2","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=Lm60Fp2hw9Y%3d&tabid=3205&portalid=0&mid=10752","caps_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=uVcOcx728Y8%3d&tabid=570&portalid=0&mid=1558","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/phsc-11","coverage":"Selected grade revision from other terms, including later-term content. Not a second paper covering only the selected term.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content.","set_id":"B","set_label":"Mixed grade revision","cognitive_framework":"CAPS subject taxonomy","cognitive_levels":["Recall","Comprehension","Analysis and application","Evaluation and synthesis"],"classification_status":"Draft author classification; independent moderation pending","assessment_note":"Five-question formative samples do not reproduce formal examination mark weightings or assess extended written responses.","source_terms":[3,4],"atp_urls":["https://www.education.gov.za/LinkClick.aspx?fileticket=Lm60Fp2hw9Y%3d&tabid=3205&portalid=0&mid=10752"],"question_reuse":"Revision questions recur across term-focused and mixed sets; Set A and Set B within the same selection do not share questions."}},{"id":"c54ea42a-a0a9-516c-99d5-f0e0ab82dc81","title":"Physical Sciences · Grade 11 · Term 3 selection · Set B: Mixed revision","subject":"Physical Sciences","grade":"Grade 11","questions":[{"question":"A 6 Ω resistor carries 2 A. Find the potential difference across it.","options":["3 V","8 V","12 V","0.33 V"],"correct_index":2,"explanation":"Ohm's law gives V=IR=2×6=12 V for an ohmic resistor under constant physical conditions.","cognitive_level":{"code":"L3","label":"Analysis and application","band":"middle"}},{"question":"A coil experiences a larger rate of change of magnetic flux. What happens to the magnitude of induced emf, all else equal?","options":["It necessarily becomes zero","It increases","It decreases to half","It depends only on the coil's colour"],"correct_index":1,"explanation":"Faraday's law relates induced emf magnitude to the rate of change of flux linkage. Faster change gives a larger emf for the same coil.","cognitive_level":{"code":"L2","label":"Comprehension","band":"lower"}},{"question":"For Zn → Zn²⁺ + 2e⁻, what happens to zinc?","options":["It is reduced by losing electrons","It is oxidised by losing electrons","It gains two electrons","Its oxidation number decreases"],"correct_index":1,"explanation":"Oxidation is loss of electrons. Zinc's oxidation number rises from 0 to +2.","cognitive_level":{"code":"L2","label":"Comprehension","band":"lower"}},{"question":"Which equation shows neutralisation of HCl by NaOH?","options":["HCl + NaOH → H₂ + NaClO","HCl + NaOH → Na + Cl + O₂","HCl + NaOH → NaCl + H₂O","HCl + NaOH → NaCl only"],"correct_index":2,"explanation":"The acid and base produce salt and water. Check that hydrogen and oxygen atoms are conserved as well as sodium and chlorine.","cognitive_level":{"code":"L2","label":"Comprehension","band":"lower"}},{"question":"A learner dilutes 100 mL of 0.4 mol·dm⁻³ solution to a final volume of 400 mL and claims the moles become one quarter. Which correction is right?","options":["Moles become 0.01 mol; concentration stays 0.4 mol·dm⁻³.","Both moles and concentration remain unchanged.","Moles remain 0.04 mol; concentration becomes 0.1 mol·dm⁻³.","Adding water creates additional solute moles."],"correct_index":2,"explanation":"Initial moles are 0.4×0.100=0.04 mol. Without loss or reaction, dilution changes volume, not solute amount. Final concentration is 0.04/0.400=0.1 mol·dm⁻³.","cognitive_level":{"code":"L3","label":"Analysis and application","band":"middle"}}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Mixed grade revision drawn from the other two terms. Includes later-term topics; revisit after studying those topics. Questions are reused deliberately across revision sets.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":5,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-3","formative","phsc"],"metadata":{"term":3,"focus":"Mixed revision: Electricity and intermolecular forces; Acid–base and redox reactions","language":"en","content_version":"2026-10-21.2","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=Lm60Fp2hw9Y%3d&tabid=3205&portalid=0&mid=10752","caps_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=uVcOcx728Y8%3d&tabid=570&portalid=0&mid=1558","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/phsc-11","coverage":"Selected grade revision from other terms, including later-term content. Not a second paper covering only the selected term.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content.","set_id":"B","set_label":"Mixed grade revision","cognitive_framework":"CAPS subject taxonomy","cognitive_levels":["Recall","Comprehension","Analysis and application","Evaluation and synthesis"],"classification_status":"Draft author classification; independent moderation pending","assessment_note":"Five-question formative samples do not reproduce formal examination mark weightings or assess extended written responses.","source_terms":[2,4],"atp_urls":["https://www.education.gov.za/LinkClick.aspx?fileticket=Lm60Fp2hw9Y%3d&tabid=3205&portalid=0&mid=10752"],"question_reuse":"Revision questions recur across term-focused and mixed sets; Set A and Set B within the same selection do not share questions."}},{"id":"11f2dc39-f31e-5c70-b7f9-2513a9a1e0d9","title":"Physical Sciences · Grade 11 · Term 4 selection · Set B: Mixed revision","subject":"Physical Sciences","grade":"Grade 11","questions":[{"question":"A 6 Ω resistor carries 2 A. Find the potential difference across it.","options":["3 V","8 V","12 V","0.33 V"],"correct_index":2,"explanation":"Ohm's law gives V=IR=2×6=12 V for an ohmic resistor under constant physical conditions.","cognitive_level":{"code":"L3","label":"Analysis and application","band":"middle"}},{"question":"A coil experiences a larger rate of change of magnetic flux. What happens to the magnitude of induced emf, all else equal?","options":["It necessarily becomes zero","It increases","It decreases to half","It depends only on the coil's colour"],"correct_index":1,"explanation":"Faraday's law relates induced emf magnitude to the rate of change of flux linkage. Faster change gives a larger emf for the same coil.","cognitive_level":{"code":"L2","label":"Comprehension","band":"lower"}},{"question":"For 2H₂ + O₂ → 2H₂O, how many moles of O₂ react with 6 mol H₂, with enough O₂ available?","options":["3 mol","6 mol","12 mol","2 mol"],"correct_index":0,"explanation":"The mole ratio H₂:O₂ is 2:1, so 6 mol H₂ needs 6/2=3 mol O₂. Coefficients describe mole ratios, not gram ratios.","cognitive_level":{"code":"L3","label":"Analysis and application","band":"middle"}},{"question":"A fixed amount of gas occupies 4 L at 100 kPa. At constant temperature, find its volume at 200 kPa.","options":["8 L","2 L","4 L","0.5 L"],"correct_index":1,"explanation":"Boyle's law: P₁V₁=P₂V₂. V₂=100×4/200=2 L. Doubling pressure halves volume at constant temperature.","cognitive_level":{"code":"L3","label":"Analysis and application","band":"middle"}},{"question":"A sealed gas sample is compressed from 4 L to 2 L while warming. A learner uses Boyle's law to assert its pressure exactly doubles. What is missing?","options":["The gas container's paint colour.","The assertion is exact at every temperature.","The temperature change; Boyle's law alone requires constant temperature.","Compression means the number of molecules must halve."],"correct_index":2,"explanation":"For a fixed amount of gas, PV/T is constant in the ideal model. Pressure also depends on absolute temperature; warming means the constant-temperature doubling claim is unjustified.","cognitive_level":{"code":"L4","label":"Evaluation and synthesis","band":"higher"}}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Mixed grade revision drawn from the other two terms. Includes later-term topics; revisit after studying those topics. Questions are reused deliberately across revision sets.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":5,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-4","formative","phsc"],"metadata":{"term":4,"focus":"Mixed revision: Electricity and intermolecular forces; Stoichiometry, gases and energy change","language":"en","content_version":"2026-10-21.2","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=Lm60Fp2hw9Y%3d&tabid=3205&portalid=0&mid=10752","caps_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=uVcOcx728Y8%3d&tabid=570&portalid=0&mid=1558","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/phsc-11","coverage":"Selected grade revision from other terms, including later-term content. Not a second paper covering only the selected term.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content.","set_id":"B","set_label":"Mixed grade revision","cognitive_framework":"CAPS subject taxonomy","cognitive_levels":["Recall","Comprehension","Analysis and application","Evaluation and synthesis"],"classification_status":"Draft author classification; independent moderation pending","assessment_note":"Five-question formative samples do not reproduce formal examination mark weightings or assess extended written responses.","source_terms":[2,3],"atp_urls":["https://www.education.gov.za/LinkClick.aspx?fileticket=Lm60Fp2hw9Y%3d&tabid=3205&portalid=0&mid=10752"],"question_reuse":"Revision questions recur across term-focused and mixed sets; Set A and Set B within the same selection do not share questions."}},{"id":"2b72a17a-3c64-5346-8f75-daa2d74931ef","title":"Life Sciences · Grade 11 · Term 2 selection · Set B: Mixed revision","subject":"Life Sciences","grade":"Grade 11","questions":[{"question":"Why are alveolar walls thin and moist?","options":["To support rapid diffusion of gases","To prevent all gas movement","To produce urine","To store solid food"],"correct_index":0,"explanation":"A thin surface shortens diffusion distance; moisture allows gases to dissolve before diffusing across the exchange surface.","cognitive_level":{"code":"L2","label":"Understanding science","band":"lower"}},{"question":"A population gains 30 births and 10 immigrants, with 20 deaths and 5 emigrants. Find its net change.","options":["Increase of 45","Decrease of 15","Increase of 65","Increase of 15"],"correct_index":3,"explanation":"Change = births+immigration−deaths−emigration = 30+10−20−5 = +15 individuals.","cognitive_level":{"code":"L3","label":"Applying scientific knowledge","band":"middle"}},{"question":"Why does destroying wetlands threaten water quality?","options":["Wetlands have no role in water movement","Wetlands create all pollutants","Wetlands can trap sediments and help filter pollutants","Wetlands prevent every flood regardless of size"],"correct_index":2,"explanation":"Wetlands provide important filtration and flow-regulation services. Their protection reduces risks, although it cannot eliminate all pollution or flooding.","cognitive_level":{"code":"L2","label":"Understanding science","band":"lower"}},{"question":"Which action most directly lowers a school's electricity-related carbon footprint when electricity comes from fossil fuels?","options":["Leave empty classrooms fully lit","Burn litter behind the classroom","Replace every indigenous tree with concrete","Reduce unnecessary electricity consumption"],"correct_index":3,"explanation":"Using less fossil-fuel-generated electricity reduces associated emissions. Measure energy use to assess whether the intervention works.","cognitive_level":{"code":"L1","label":"Knowing science","band":"lower"}},{"question":"A dam has an algal bloom followed by fish deaths. Which evidence most directly tests oxygen depletion during decomposition?","options":["Only the colour of a poster about the dam.","A count of fish species with no water measurements.","Dissolved-oxygen measurements over time, compared with less-affected water and decomposition indicators.","An assumption that all algae directly poison every fish."],"correct_index":2,"explanation":"Tracking oxygen decline alongside organic decay tests the proposed mechanism. Comparison water and repeated measurements help distinguish it from other causes such as a toxic discharge.","cognitive_level":{"code":"L4","label":"Evaluating, analysing and synthesising","band":"higher"}}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Mixed grade revision drawn from the other two terms. Includes later-term topics; revisit after studying those topics. Questions are reused deliberately across revision sets.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":5,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-2","formative","lisc"],"metadata":{"term":2,"focus":"Mixed revision: Gas exchange, excretion and populations; Human impact and environmental evidence","language":"en","content_version":"2026-10-21.2","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=bj82jNMC2qg%3d&tabid=3205&portalid=0&mid=10752","caps_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=_yUNfV0A_8o%3d&tabid=570&portalid=0&mid=1558","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/lisc-11","coverage":"Selected grade revision from other terms, including later-term content. Not a second paper covering only the selected term.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content.","set_id":"B","set_label":"Mixed grade revision","cognitive_framework":"CAPS subject taxonomy","cognitive_levels":["Knowing science","Understanding science","Applying scientific knowledge","Evaluating, analysing and synthesising"],"classification_status":"Draft author classification; independent moderation pending","assessment_note":"Five-question formative samples do not reproduce formal examination mark weightings or assess extended written responses.","source_terms":[3,4],"atp_urls":["https://www.education.gov.za/LinkClick.aspx?fileticket=bj82jNMC2qg%3d&tabid=3205&portalid=0&mid=10752"],"question_reuse":"Revision questions recur across term-focused and mixed sets; Set A and Set B within the same selection do not share questions."}},{"id":"3ac6dae2-da2a-5976-ad8e-6e124ee4760b","title":"Life Sciences · Grade 11 · Term 3 selection · Set B: Mixed revision","subject":"Life Sciences","grade":"Grade 11","questions":[{"question":"Which gas is taken in as a raw material for photosynthesis?","options":["Oxygen","Nitrogen only","Hydrogen","Carbon dioxide"],"correct_index":3,"explanation":"Photosynthesis uses carbon dioxide and water to produce organic compounds using light energy. Oxygen is released as a by-product.","cognitive_level":{"code":"L1","label":"Knowing science","band":"lower"}},{"question":"Where does most absorption of digested nutrients occur in humans?","options":["Oesophagus","Large intestine only","Small intestine","Stomach only"],"correct_index":2,"explanation":"The small intestine has villi and microvilli that increase surface area for absorption of digested nutrients.","cognitive_level":{"code":"L1","label":"Knowing science","band":"lower"}},{"question":"Why does destroying wetlands threaten water quality?","options":["Wetlands have no role in water movement","Wetlands create all pollutants","Wetlands can trap sediments and help filter pollutants","Wetlands prevent every flood regardless of size"],"correct_index":2,"explanation":"Wetlands provide important filtration and flow-regulation services. Their protection reduces risks, although it cannot eliminate all pollution or flooding.","cognitive_level":{"code":"L2","label":"Understanding science","band":"lower"}},{"question":"Which action most directly lowers a school's electricity-related carbon footprint when electricity comes from fossil fuels?","options":["Leave empty classrooms fully lit","Burn litter behind the classroom","Replace every indigenous tree with concrete","Reduce unnecessary electricity consumption"],"correct_index":3,"explanation":"Using less fossil-fuel-generated electricity reduces associated emissions. Measure energy use to assess whether the intervention works.","cognitive_level":{"code":"L1","label":"Knowing science","band":"lower"}},{"question":"A dam has an algal bloom followed by fish deaths. Which evidence most directly tests oxygen depletion during decomposition?","options":["Only the colour of a poster about the dam.","A count of fish species with no water measurements.","Dissolved-oxygen measurements over time, compared with less-affected water and decomposition indicators.","An assumption that all algae directly poison every fish."],"correct_index":2,"explanation":"Tracking oxygen decline alongside organic decay tests the proposed mechanism. Comparison water and repeated measurements help distinguish it from other causes such as a toxic discharge.","cognitive_level":{"code":"L4","label":"Evaluating, analysing and synthesising","band":"higher"}}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Mixed grade revision drawn from the other two terms. Includes later-term topics; revisit after studying those topics. Questions are reused deliberately across revision sets.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":5,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-3","formative","lisc"],"metadata":{"term":3,"focus":"Mixed revision: Photosynthesis, respiration and nutrition; Human impact and environmental evidence","language":"en","content_version":"2026-10-21.2","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=bj82jNMC2qg%3d&tabid=3205&portalid=0&mid=10752","caps_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=_yUNfV0A_8o%3d&tabid=570&portalid=0&mid=1558","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/lisc-11","coverage":"Selected grade revision from other terms, including later-term content. Not a second paper covering only the selected term.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content.","set_id":"B","set_label":"Mixed grade revision","cognitive_framework":"CAPS subject taxonomy","cognitive_levels":["Knowing science","Understanding science","Applying scientific knowledge","Evaluating, analysing and synthesising"],"classification_status":"Draft author classification; independent moderation pending","assessment_note":"Five-question formative samples do not reproduce formal examination mark weightings or assess extended written responses.","source_terms":[2,4],"atp_urls":["https://www.education.gov.za/LinkClick.aspx?fileticket=bj82jNMC2qg%3d&tabid=3205&portalid=0&mid=10752"],"question_reuse":"Revision questions recur across term-focused and mixed sets; Set A and Set B within the same selection do not share questions."}},{"id":"d6b820e8-729a-58af-8b81-000e4e14cf42","title":"Life Sciences · Grade 11 · Term 4 selection · Set B: Mixed revision","subject":"Life Sciences","grade":"Grade 11","questions":[{"question":"Which gas is taken in as a raw material for photosynthesis?","options":["Oxygen","Nitrogen only","Hydrogen","Carbon dioxide"],"correct_index":3,"explanation":"Photosynthesis uses carbon dioxide and water to produce organic compounds using light energy. Oxygen is released as a by-product.","cognitive_level":{"code":"L1","label":"Knowing science","band":"lower"}},{"question":"Where does most absorption of digested nutrients occur in humans?","options":["Oesophagus","Large intestine only","Small intestine","Stomach only"],"correct_index":2,"explanation":"The small intestine has villi and microvilli that increase surface area for absorption of digested nutrients.","cognitive_level":{"code":"L1","label":"Knowing science","band":"lower"}},{"question":"Which organ removes urea from the blood and helps regulate water balance?","options":["Stomach","Kidney","Heart","Pancreas only"],"correct_index":1,"explanation":"Kidneys filter blood and form urine, removing nitrogenous wastes and regulating water and salts. The liver produces urea from excess amino nitrogen.","cognitive_level":{"code":"L1","label":"Knowing science","band":"lower"}},{"question":"What happens when ADH secretion increases in a healthy person?","options":["Less water is reabsorbed and all urine stops","Blood sugar always doubles","More water is reabsorbed, usually producing a smaller volume of more concentrated urine","No kidney response is possible"],"correct_index":2,"explanation":"ADH increases water reabsorption in the kidney, generally reducing urine volume and making it more concentrated. Distinguish urine volume from concentration.","cognitive_level":{"code":"L2","label":"Understanding science","band":"lower"}},{"question":"A population rises by 15 after 30 births, 20 deaths, 10 immigrants and 5 emigrants. Which prediction about next year is warranted?","options":["It must rise by exactly 15 every year.","Births alone guarantee a rise of 30.","No exact prediction follows without next year's rates and conditions.","Immigration proves deaths will stop."],"correct_index":2,"explanation":"The net change describes one interval: 30+10−20−5=15. Future births, deaths, migration and resource limits may differ, so extrapolating the same change as a certainty is unjustified.","cognitive_level":{"code":"L4","label":"Evaluating, analysing and synthesising","band":"higher"}}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Mixed grade revision drawn from the other two terms. Includes later-term topics; revisit after studying those topics. Questions are reused deliberately across revision sets.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":5,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-4","formative","lisc"],"metadata":{"term":4,"focus":"Mixed revision: Photosynthesis, respiration and nutrition; Gas exchange, excretion and populations","language":"en","content_version":"2026-10-21.2","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=bj82jNMC2qg%3d&tabid=3205&portalid=0&mid=10752","caps_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=_yUNfV0A_8o%3d&tabid=570&portalid=0&mid=1558","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/lisc-11","coverage":"Selected grade revision from other terms, including later-term content. Not a second paper covering only the selected term.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content.","set_id":"B","set_label":"Mixed grade revision","cognitive_framework":"CAPS subject taxonomy","cognitive_levels":["Knowing science","Understanding science","Applying scientific knowledge","Evaluating, analysing and synthesising"],"classification_status":"Draft author classification; independent moderation pending","assessment_note":"Five-question formative samples do not reproduce formal examination mark weightings or assess extended written responses.","source_terms":[2,3],"atp_urls":["https://www.education.gov.za/LinkClick.aspx?fileticket=bj82jNMC2qg%3d&tabid=3205&portalid=0&mid=10752"],"question_reuse":"Revision questions recur across term-focused and mixed sets; Set A and Set B within the same selection do not share questions."}},{"id":"5b7ecdd2-0ffb-5495-b90e-81bb677a30b3","title":"Accounting · Grade 11 · Term 2 selection · Set B: Mixed revision","subject":"Accounting","grade":"Grade 11","questions":[{"question":"A cash sale of R500 occurs in March. Where does it appear in the cash budget?","options":["April receipts automatically","March receipts","March payments","Nowhere because sales are not cash"],"correct_index":1,"explanation":"A cash budget records the timing of actual cash movements. A cash sale is received in March; credit collections need a collection schedule.","cognitive_level":{"code":"L1","label":"Knowledge and comprehension","band":"lower"}},{"question":"Which statement distinguishes perpetual from periodic inventory?","options":["Perpetual records continuously update stock and cost of sales; periodic calculates cost of sales at intervals","Periodic means stock is never counted","Perpetual means stock cannot be stolen","Both systems forbid stocktaking"],"correct_index":0,"explanation":"The systems differ in recording timing. Physical stocktaking remains useful for verifying balances and identifying losses.","cognitive_level":{"code":"L1","label":"Knowledge and comprehension","band":"lower"}},{"question":"Output VAT is R9 000 and deductible input VAT R6 500. Find the net VAT payable.","options":["R15 500","R6 500","R9 000","R2 500"],"correct_index":3,"explanation":"Net VAT payable = output−deductible input = R2 500. If deductible input exceeded output, the position would instead be receivable, subject to rules.","cognitive_level":{"code":"L2","label":"Application and analysis","band":"middle"}},{"question":"For this exercise VAT is 15%. Extract VAT from a VAT-inclusive amount of R230.","options":["R30","R34.50","R200","R15"],"correct_index":0,"explanation":"VAT = inclusive amount×15/115 = 230×15/115 = R30. Taking 15% of the inclusive total uses the wrong base.","cognitive_level":{"code":"L2","label":"Application and analysis","band":"middle"}},{"question":"A VAT return includes an input claim supported only by a handwritten total with no valid tax invoice. What should the accountant do?","options":["Claim it automatically because any total proves eligibility.","Create an invoice in the supplier's name without authorisation.","Verify eligibility and obtain the required evidence before including the claim.","Increase output VAT to hide the unsupported claim."],"correct_index":2,"explanation":"An input-VAT claim needs qualifying expenditure and supporting documentation under applicable rules. Investigate and obtain valid evidence rather than fabricate records or assume every purchase qualifies.","cognitive_level":{"code":"L3","label":"Synthesis and evaluation","band":"higher"}}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Mixed grade revision drawn from the other two terms. Includes later-term topics; revisit after studying those topics. Questions are reused deliberately across revision sets.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":5,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-2","formative","acc"],"metadata":{"term":2,"focus":"Mixed revision: Budgets, inventory and manufacturing; VAT and accounting revision","language":"en","content_version":"2026-10-21.2","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=qxPOjU7FXcA%3d&tabid=3205&portalid=0&mid=10752","caps_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=IIU4LUlZBFM%3d&tabid=570&portalid=0&mid=1558","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/acc-11","coverage":"Selected grade revision from other terms, including later-term content. Not a second paper covering only the selected term.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content.","set_id":"B","set_label":"Mixed grade revision","cognitive_framework":"CAPS subject taxonomy","cognitive_levels":["Knowledge and comprehension","Application and analysis","Synthesis and evaluation"],"classification_status":"Draft author classification; independent moderation pending","assessment_note":"Five-question formative samples do not reproduce formal examination mark weightings or assess extended written responses.","source_terms":[3,4],"atp_urls":["https://www.education.gov.za/LinkClick.aspx?fileticket=qxPOjU7FXcA%3d&tabid=3205&portalid=0&mid=10752"],"question_reuse":"Revision questions recur across term-focused and mixed sets; Set A and Set B within the same selection do not share questions."}},{"id":"7a0a3079-a989-5801-a8f6-d32b1ad94c41","title":"Accounting · Grade 11 · Term 3 selection · Set B: Mixed revision","subject":"Accounting","grade":"Grade 11","questions":[{"question":"A partnership earns R90 000 before appropriations. Partner salaries total R30 000; no other appropriations apply. Find residual profit.","options":["R60 000","R120 000","R30 000","R90 000"],"correct_index":0,"explanation":"Residual profit = profit available−partner salaries−other appropriations. Here 90 000−30 000=R60 000, shared using the agreed ratio.","cognitive_level":{"code":"L2","label":"Application and analysis","band":"middle"}},{"question":"Why compare a partnership's financial indicators with prior years?","options":["To prove future profit is guaranteed","To avoid reading the financial statements","To ignore different business conditions","To identify trends and investigate performance changes"],"correct_index":3,"explanation":"Comparisons help interpret performance, but context such as changing prices, policies and business conditions still matters.","cognitive_level":{"code":"L2","label":"Application and analysis","band":"middle"}},{"question":"Output VAT is R9 000 and deductible input VAT R6 500. Find the net VAT payable.","options":["R15 500","R6 500","R9 000","R2 500"],"correct_index":3,"explanation":"Net VAT payable = output−deductible input = R2 500. If deductible input exceeded output, the position would instead be receivable, subject to rules.","cognitive_level":{"code":"L2","label":"Application and analysis","band":"middle"}},{"question":"For this exercise VAT is 15%. Extract VAT from a VAT-inclusive amount of R230.","options":["R30","R34.50","R200","R15"],"correct_index":0,"explanation":"VAT = inclusive amount×15/115 = 230×15/115 = R30. Taking 15% of the inclusive total uses the wrong base.","cognitive_level":{"code":"L2","label":"Application and analysis","band":"middle"}},{"question":"A VAT return includes an input claim supported only by a handwritten total with no valid tax invoice. What should the accountant do?","options":["Claim it automatically because any total proves eligibility.","Create an invoice in the supplier's name without authorisation.","Verify eligibility and obtain the required evidence before including the claim.","Increase output VAT to hide the unsupported claim."],"correct_index":2,"explanation":"An input-VAT claim needs qualifying expenditure and supporting documentation under applicable rules. Investigate and obtain valid evidence rather than fabricate records or assume every purchase qualifies.","cognitive_level":{"code":"L3","label":"Synthesis and evaluation","band":"higher"}}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Mixed grade revision drawn from the other two terms. Includes later-term topics; revisit after studying those topics. Questions are reused deliberately across revision sets.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":5,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-3","formative","acc"],"metadata":{"term":3,"focus":"Mixed revision: Partnership statements and analysis; VAT and accounting revision","language":"en","content_version":"2026-10-21.2","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=qxPOjU7FXcA%3d&tabid=3205&portalid=0&mid=10752","caps_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=IIU4LUlZBFM%3d&tabid=570&portalid=0&mid=1558","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/acc-11","coverage":"Selected grade revision from other terms, including later-term content. Not a second paper covering only the selected term.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content.","set_id":"B","set_label":"Mixed grade revision","cognitive_framework":"CAPS subject taxonomy","cognitive_levels":["Knowledge and comprehension","Application and analysis","Synthesis and evaluation"],"classification_status":"Draft author classification; independent moderation pending","assessment_note":"Five-question formative samples do not reproduce formal examination mark weightings or assess extended written responses.","source_terms":[2,4],"atp_urls":["https://www.education.gov.za/LinkClick.aspx?fileticket=qxPOjU7FXcA%3d&tabid=3205&portalid=0&mid=10752"],"question_reuse":"Revision questions recur across term-focused and mixed sets; Set A and Set B within the same selection do not share questions."}},{"id":"52a3dae8-7091-58e6-a521-28606fd524ae","title":"Accounting · Grade 11 · Term 4 selection · Set B: Mixed revision","subject":"Accounting","grade":"Grade 11","questions":[{"question":"A partnership earns R90 000 before appropriations. Partner salaries total R30 000; no other appropriations apply. Find residual profit.","options":["R60 000","R120 000","R30 000","R90 000"],"correct_index":0,"explanation":"Residual profit = profit available−partner salaries−other appropriations. Here 90 000−30 000=R60 000, shared using the agreed ratio.","cognitive_level":{"code":"L2","label":"Application and analysis","band":"middle"}},{"question":"Why compare a partnership's financial indicators with prior years?","options":["To prove future profit is guaranteed","To avoid reading the financial statements","To ignore different business conditions","To identify trends and investigate performance changes"],"correct_index":3,"explanation":"Comparisons help interpret performance, but context such as changing prices, policies and business conditions still matters.","cognitive_level":{"code":"L2","label":"Application and analysis","band":"middle"}},{"question":"A business expects 60% of credit sales of R20 000 to be collected next month. Find that collection.","options":["R8 000","R20 000","R12 000","R32 000"],"correct_index":2,"explanation":"Multiply credit sales by the collection proportion: 20 000×0.60=R12 000. The rest is collected later or subject to other assumptions.","cognitive_level":{"code":"L2","label":"Application and analysis","band":"middle"}},{"question":"Fixed costs are R30 000; selling price is R50 per unit and variable cost R20. Find break-even units.","options":["600","1 500","10 000","1 000"],"correct_index":3,"explanation":"Contribution per unit = 50−20=R30. Break-even = fixed costs/contribution = 30 000/30 = 1 000 units.","cognitive_level":{"code":"L2","label":"Application and analysis","band":"middle"}},{"question":"A business forecasts R12 000 collections next month from R20 000 credit sales. Debtor payment delays are increasing. What is the best budget response?","options":["Keep the forecast unchanged because a policy guarantees payment.","Record all R20 000 as cash received immediately.","Test lower or later collections and plan for possible funding needs.","Remove all sales from the income statement."],"correct_index":2,"explanation":"A collection policy is an estimate, not a guarantee. Actual debtor behaviour informs a more realistic timing forecast; sensitivity checks show the cash effect of delayed or reduced receipts.","cognitive_level":{"code":"L3","label":"Synthesis and evaluation","band":"higher"}}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Mixed grade revision drawn from the other two terms. Includes later-term topics; revisit after studying those topics. Questions are reused deliberately across revision sets.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":5,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-4","formative","acc"],"metadata":{"term":4,"focus":"Mixed revision: Partnership statements and analysis; Budgets, inventory and manufacturing","language":"en","content_version":"2026-10-21.2","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=qxPOjU7FXcA%3d&tabid=3205&portalid=0&mid=10752","caps_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=IIU4LUlZBFM%3d&tabid=570&portalid=0&mid=1558","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/acc-11","coverage":"Selected grade revision from other terms, including later-term content. Not a second paper covering only the selected term.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content.","set_id":"B","set_label":"Mixed grade revision","cognitive_framework":"CAPS subject taxonomy","cognitive_levels":["Knowledge and comprehension","Application and analysis","Synthesis and evaluation"],"classification_status":"Draft author classification; independent moderation pending","assessment_note":"Five-question formative samples do not reproduce formal examination mark weightings or assess extended written responses.","source_terms":[2,3],"atp_urls":["https://www.education.gov.za/LinkClick.aspx?fileticket=qxPOjU7FXcA%3d&tabid=3205&portalid=0&mid=10752"],"question_reuse":"Revision questions recur across term-focused and mixed sets; Set A and Set B within the same selection do not share questions."}}]$smartbridge$::jsonb)
